// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    // Fuzz the caller address: for any caller, only the owner (deployer) may succeed.
    function testFuzz_property(address caller) public {
        // Keep domain wide but avoid the zero address because prank with address(0) is not meaningful here.
        vm.assume(caller != address(0));

        // Ensure caller has some ETH so calls that send value (if any) won't fail due to lack of funds.
        vm.deal(caller, 1 wei);

        bool ok;
        // run the call as the fuzzed caller
        vm.prank(caller);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // The contract was deployed in setUp() by this test contract, so the owner is address(this).
        // Rule: only the owner (address(this)) can successfully call sudicideAnyone.
        // So for any caller: ok == (caller == address(this))
        assertTrue(ok == (caller == address(this)));
    }
}
